INSERT INTO `tb_halamans` (`id`, `judul`, `slug`, `atas_kiri`, `atas_tengah`, `atas_kanan`, `tengah_kiri`, `tengah`, `tengah_kanan`, `bawah_kiri`, `bawah_tengah`, `bawah_kanan`, `teks`, `gambar`, `created_at`, `updated_at`, `deleted_at`) VALUES
(50, 'Visi Misi', 'visi-misi', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', '<p><strong>Visi </strong></p>\r\n\r\n<p>Menjadi Perusahaan Jasa Dan Perdagangan UmumYang Tumbuh Dan Berkembang Serta Mampu Memenuhi Kebutuhan Konsumen</p>\r\n\r\n<p><strong>Misi</strong></p>\r\n\r\n<ol>\r\n	<li>Komitmen Dalam Kualitas Layanan</li>\r\n	<li>Profesional Dalam Bekerja</li>\r\n	<li>Tepat Waktu &amp; Bermutu</li>\r\n</ol>', NULL, '2025-05-20 04:08:18', '2025-05-20 04:08:18', NULL),
(51, 'Tentang Kami', 'tentang-kami', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', '<p>PT. Synthesa Group Indonesia atau kami biasa singkat dengan sebutan &ldquo;SGI&rdquo; Sebagai perusahaan yang bergerak dibidang pengadaan barang dan jasa yang didirikan pada tahun 2005 yang awalnya dalam bentuk CV lalu 2024 berubah menjadi PT oleh para pendiri yang memiliki Potensi dan Keahlian yang berbeda, dengan latar belakang inilah perusahaan kami dinamakan &ldquo;Synthesa&rdquo; yang artinya Penuh warna atau warna-warni.</p>\r\n\r\n<p>Kami menyediakan solusi bisnis yang inovatif kepada perusahaan yang menjadi mitra kami ,yang mana kami selalu mengutamakan mutu serta kepercayaan demi kelangsungan bisnis yang harmonis dan berkelanjutan.</p>\r\n\r\n<p>Tujuan kami adalah untuk menjadi pilihan utama bagi mitra bisnis kami dengan memberikan kontribusi kepada setiap klien kami, melebihi dari yang mereka harapkan, melalui pelayanan istimewa dari kami secara profesional dan integritas penuh.</p>\r\n\r\n<p>PT. Synthesa Group Indonesia dalam menjalankan bisnis di dukung oleh sumber daya yang berkualitas dan berpengalaman. Karena kami yakin, hanya dengan sumber daya yang tinggi kami dapat menghasilkan kualitas pekerjaan dan pelayanan yang baik sesuai yang di harapkan mitra bisnis kami.</p>', NULL, '2025-05-20 04:08:53', '2025-05-20 04:08:53', NULL),
(52, 'Kontak', 'kontak', 'Tidak', 'Kontak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', NULL, NULL, '2025-05-20 04:09:03', '2025-05-20 04:09:03', NULL),
(53, 'Layanan', 'layanan', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', 'Tidak', '<ul>\r\n	<li>Training IT &amp; SDM</li>\r\n	<li>Financial Consultant Design &amp; Clothing</li>\r\n	<li>Contructor</li>\r\n	<li>Advertising</li>\r\n</ul>', NULL, '2025-05-20 04:09:58', '2025-05-20 04:09:58', NULL);
