INSERT INTO `tb_pertanyans` (`id`, `pertanyaan`, `jawaban`, `created_at`, `updated_at`) VALUES
(1, 'Apa itu \"Belajar.link\"?', 'Platform pembelajaran online yang di peruntukan untuk umum dengan ketersediaan pembelajaran pembelajaran yang menjurus kepada keahlian diri.', NULL, '2022-11-24 23:32:09'),
(2, 'Metode Pembayaran dapat dilakukan via apa saja?', 'Anda dapat membayar melalui alfamart, indomaret, dan e-wallet.', NULL, '2022-11-16 23:29:18'),
(3, 'Siapa saja yang dapat menggunakan \"belajar.link\"?', 'Platform pembelajaran yang tidak di batasi oleh jenjang ini bisa di akses oleh siapa saja dengan profesi apapun.', NULL, '2022-11-24 23:22:32'),
(4, 'Bagaimana cara mendaftarnya?', 'Bisa langsung di klik aja ya \"Berlangganan Sekarang\", kemudian klik \"daftar disini\", setelah mengisi data lalu kamu bisa langsung login dan dapat mengakses paket yang tersedia.', NULL, '2022-11-24 23:32:57'),
(5, 'Paket yang sudah di pesan apakah memiliki batas akses?', 'Paket yang sudah di pesan tidak ada batas akses, kamu dapat mengakses nya selama masih menggunakan \"belajar.link\"', NULL, '2022-11-24 23:25:01'),
(6, 'Apakah akun yang sudah berlangganan, bisa akses lebih dari satu perangkat?', 'Tentu saja bisa.', NULL, '2022-11-24 22:42:38');
INSERT INTO `tb_program_donasi` (`id`, `id_user`, `judul`, `tgl_pembuatan`, `waktu_pembuatan`, `slug`, `deskripsi`, `rekening`, `gambar`, `viewer`, `created_at`, `updated_at`, `deleted_at`) VALUES
(7, 1, 'Pembangunan Masjid Penghafal Al-Qur’an', '2025-05-26', '17:06', 'pembangunan-masjid-penghafal-al-quran', '<p>Pembangunan ini bertujuan sebagai sarana tempat ibadah untuk semua masyarakat dan sebagai sarana tempat pesantren pendidikan agama penghafal al-qur&rsquo;an Anak Shaleh Foundation. setelah peletakan batu pertama dilakukan, progres saat ini telah dilakukan pemadatan lahan, dan saat ini belum dilakukan progres pondasi pada pembangunan masjid karena masih terkendala dengan biaya.</p>', '<p><strong>- 0682723891</strong></p>', '9762Investasi-Akhirat.png', '0', '2025-05-26 03:06:45', '2025-06-02 00:37:08', NULL),
(8, 1, 'Fidyah 1446 H', '2025-06-02', '14:34', 'fidyah-1446-h', '<p><strong>LALU BERAPA BESARAN FIDYAH?</strong></p>\r\n\r\n<p>&ldquo;Dan wajib bagi orang yang berat menjalankannya (puasa) membayar fidyah, yaitu memberi makan orang miskin.&rdquo; (QS. Al-Baqarah: 184)</p>\r\n\r\n<p>Cara membayar Fidyah adalah dengan memberi makan kepada yatim &amp; dhuafa berdasarkan pada jumlah puasa yang ditinggalkan.</p>\r\n\r\n<p>Besaran fidyah yang perlu dibayarkan minimal sebesar 1 mud, atau setara dengan 3/4 liter makanan pokok. Ada pula ulama yang mengatakan, besaran fidyah sebanyak 2 mud atau setara 1,5 kg makanan pokok.</p>\r\n\r\n<p>Ada pula yang mengatakan sebanyak 1 sha atau setara dengan 2,75 liter makanan pokok. Namun, lebih baik membayarnya dengan memberikan makan orang miskin cukup untuk sehari makan (3x sehari) dengan porsi yang cukup mengenyangkan.</p>\r\n\r\n<p>Jadi fidyah disesuaikan dengan harga satu porsi makanan yang standar yang berlaku. untuk nominal fidyah di Anak Shaleh Foundation&nbsp;<strong>Rp25.000</strong>&nbsp;untuk anak yatim piatu dhuafa dan masyarakat yang membutuhkan di Kabupaten dan Kota Bandung dalam sehari, yang sudah lengkap dengan lauk.</p>\r\n\r\n<p><strong>Salurkan fidyah terbaik Anda dengan cara:</strong></p>\r\n\r\n<ol>\r\n	<li>Klik tombol&nbsp;<strong>&ldquo;DONASI SEKARANG&rdquo;</strong></li>\r\n	<li>Lengkapi data diri</li>\r\n	<li>Pilih Nominal Donasi</li>\r\n	<li>Pilih metode pembayaran</li>\r\n	<li>Transaksi sesuai dengan metode pembayaran</li>\r\n</ol>\r\n\r\n<p><strong>Tak hanya mendoakan dan berdonasi, #SahabatKebaikan juga bisa membagikan halaman galang dana ini agar semakin banyak yang turut ikut membantu dan menunaikan fidyah</strong></p>\r\n\r\n<p>Semoga fidyah yang diberikan menjadi kebaikan dan pahala yang berlimpah untuk kita serta memberikan kebahagiaan bagi penerima manfaat. Aamiin.</p>', '<p>- 0628382377</p>\r\n\r\n<p>- 2382727222</p>', '5879fidyah1.jpg', '0', '2025-06-02 00:35:48', '2025-06-02 00:36:44', NULL);
